1	package com.example.starter.weight.service;
2	
3	import java.math.BigDecimal;
4	import java.time.Clock;
5	import java.time.Instant;
6	import java.time.LocalDate;
7	import java.time.ZoneOffset;
8	import java.time.temporal.ChronoUnit;
9	import java.util.List;
10	
11	import org.springframework.dao.DuplicateKeyException;
12	import org.springframework.stereotype.Service;
13	import org.springframework.transaction.annotation.Transactional;
14	
15	import com.example.starter.weight.api.ApiException;
16	import com.example.starter.weight.api.dto.CaseResponse;
17	import com.example.starter.weight.api.dto.DecisionRequest;
18	import com.example.starter.weight.api.dto.DecisionResponse;
19	import com.example.starter.weight.api.dto.ReviewApplyRequest;
20	import com.example.starter.weight.api.dto.ReviewConcludeRequest;
21	import com.example.starter.weight.api.dto.ReviewResponse;
22	import com.example.starter.weight.api.dto.WeighRequest;
23	import com.example.starter.weight.api.dto.WeighResponse;
24	import com.example.starter.weight.domain.CaseStatus;
25	import com.example.starter.weight.domain.DecisionStatus;
26	import com.example.starter.weight.domain.DecisionTier;
27	import com.example.starter.weight.domain.DocType;
28	import com.example.starter.weight.domain.OverloadRules;
29	import com.example.starter.weight.domain.RecordRole;
30	import com.example.starter.weight.domain.ReviewStatus;
31	import com.example.starter.weight.domain.WeighMode;
32	import com.example.starter.weight.repo.CaseRepository;
33	import com.example.starter.weight.repo.DecisionRepository;
34	import com.example.starter.weight.repo.LateWeighEventRepository;
35	import com.example.starter.weight.repo.LedgerRepository;
36	import com.example.starter.weight.repo.ReferenceRepository;
37	import com.example.starter.weight.repo.ReviewRepository;
38	import com.example.starter.weight.repo.SequenceRepository;
39	import com.example.starter.weight.repo.WeighRecordRepository;
40	import com.example.starter.weight.repo.po.CaseRow;
41	import com.example.starter.weight.repo.po.DecisionRow;
42	import com.example.starter.weight.repo.po.ReviewRow;
43	import com.example.starter.weight.repo.po.StationRow;
44	import com.example.starter.weight.repo.po.VehicleRow;
45	import com.example.starter.weight.repo.po.WeighRecordRow;
46	
47	/**
48	 * 治超执法核心服务：过磅判定、静态复检优先、处罚决定幂等、
49	 * 复检 7 日期限与唯一受理、撤销原子性、结案终态。
50	 */
51	@Service
52	public class EnforcementService {
53	
54	    private static final String REASON_PENALTY = "PENALTY";
55	    private static final String REASON_REFUND = "REVOCATION_REFUND";
56	
57	    private final ReferenceRepository referenceRepository;
58	    private final WeighRecordRepository weighRecordRepository;
59	    private final CaseRepository caseRepository;
60	    private final DecisionRepository decisionRepository;
61	    private final ReviewRepository reviewRepository;
62	    private final LedgerRepository ledgerRepository;
63	    private final LateWeighEventRepository lateWeighEventRepository;
64	    private final SequenceRepository sequenceRepository;
65	    private final Clock clock;
66	
67	    public EnforcementService(ReferenceRepository referenceRepository,
68	                              WeighRecordRepository weighRecordRepository,
69	                              CaseRepository caseRepository,
70	                              DecisionRepository decisionRepository,
71	                              ReviewRepository reviewRepository,
72	                              LedgerRepository ledgerRepository,
73	                              LateWeighEventRepository lateWeighEventRepository,
74	                              SequenceRepository sequenceRepository,
75	                              Clock clock) {
76	        this.referenceRepository = referenceRepository;
77	        this.weighRecordRepository = weighRecordRepository;
78	        this.caseRepository = caseRepository;
79	        this.decisionRepository = decisionRepository;
80	        this.reviewRepository = reviewRepository;
81	        this.ledgerRepository = ledgerRepository;
82	        this.lateWeighEventRepository = lateWeighEventRepository;
83	        this.sequenceRepository = sequenceRepository;
84	        this.clock = clock;
85	    }
86	
87	    /**
88	     * 车辆过磅上报：查限值、计算超限率与分档，按业务键去重、静态复检优先、结案后迟到备查。
89	     */
90	    @Transactional
91	    public WeighResponse submitWeigh(WeighRequest req) {
92	        Instant now = Instant.now(clock);
93	        String fingerprint = Fingerprints.of(
94	                req.requestId(), req.plateNo(), req.stationCode(), req.weighTime().toString(),
95	                req.mode().name(), req.totalKg().stripTrailingZeros().toPlainString());
96	
97	        WeighRecordRow existing = weighRecordRepository.findByRequestId(req.requestId());
98	        if (existing != null) {
99	            if (!existing.fingerprint().equals(fingerprint)) {
100	                throw ApiException.conflict("IDEMPOTENT_PARAM_CONFLICT",
101	                        "requestId 已存在但业务参数不一致，拒绝产生新记录");
102	            }
103	            return toWeighResponse(existing, true, false);
104	        }
105	
106	        VehicleRow vehicle = requireVehicle(req.plateNo());
107	        requireStation(req.stationCode());
108	        BigDecimal limitKg = referenceRepository.findLimitKg(vehicle.axleType());
109	        if (limitKg == null) {
110	            throw ApiException.unprocessable("AXLE_LIMIT_MISSING",
111	                    "轴型 " + vehicle.axleType() + " 未配置限值");
112	        }
113	        BigDecimal rate = OverloadRules.overloadRate(req.totalKg(), limitKg);
114	        DecisionTier tier = OverloadRules.tierOf(rate);
115	
116	        // 业务去重键：车牌+检测站+过磅时刻+方式
117	        WeighRecordRow sameKey = weighRecordRepository.findByDedupKey(
118	                req.plateNo(), req.stationCode(), req.weighTime(), req.mode().name());
119	        if (sameKey != null) {
120	            return toWeighResponse(sameKey, false, true);
121	        }
122	
123	        CaseRow caseRow = caseRepository.findByBizKey(
124	                req.plateNo(), req.stationCode(), req.weighTime());
125	        boolean closed = caseRow != null && CaseStatus.CLOSED.name().equals(caseRow.status());
126	
127	        String role;
128	        Long caseId;
129	        if (closed) {
130	            // 结案后迟到过磅数据：只记迟到事件并入证据备查，不改判已结案件
131	            role = RecordRole.LATE_EVIDENCE.name();
132	            caseId = caseRow.id();
133	        } else {
134	            if (caseRow == null) {
135	                caseRow = createCase(req.plateNo(), req.stationCode(), req.weighTime(), now);
136	            }
137	            caseId = caseRow.id();
138	            role = resolveLiveRole(req.plateNo(), req.stationCode(), req.weighTime(), req.mode());
139	        }
140	
141	        WeighRecordRow row = new WeighRecordRow(
142	                null, req.requestId(), fingerprint, req.plateNo(), req.stationCode(), req.weighTime(),
143	                req.mode().name(), req.totalKg(), vehicle.axleType(), limitKg, rate, tier.name(),
144	                role, caseId, now);
145	        long id;
146	        try {
147	            id = weighRecordRepository.insert(row);
148	        } catch (DuplicateKeyException e) {
149	            // 并发下幂等键或去重键已被其他事务写入，重查返回首次结果
150	            WeighRecordRow raced = weighRecordRepository.findByRequestId(req.requestId());
151	            if (raced != null) {
152	                if (!raced.fingerprint().equals(fingerprint)) {
153	                    throw ApiException.conflict("IDEMPOTENT_PARAM_CONFLICT",
154	                            "requestId 已存在但业务参数不一致，拒绝产生新记录");
155	                }
156	                return toWeighResponse(raced, true, false);
157	            }
158	            WeighRecordRow dedupRaced = weighRecordRepository.findByDedupKey(
159	                    req.plateNo(), req.stationCode(), req.weighTime(), req.mode().name());
160	            return toWeighResponse(dedupRaced, false, true);
161	        }
162	
163	        if (closed) {
164	            lateWeighEventRepository.insert(id, caseRow.id(), req.plateNo(), req.stationCode(),
165	                    req.weighTime(), req.mode().name(), req.totalKg(),
166	                    "案件 " + caseRow.caseNo() + " 已结案，迟到过磅数据仅入证据备查，不改判", now);
167	        } else if (req.mode() == WeighMode.STATIC) {
168	            // 静态复检优先：动态记录降级为被取代并保留可查
169	            weighRecordRepository.findAllByBizKey(req.plateNo(), req.stationCode(), req.weighTime())
170	                    .stream()
171	                    .filter(r -> r.mode().equals(WeighMode.DYNAMIC.name())
172	                            && RecordRole.AUTHORITATIVE.name().equals(r.role())
173	                            && r.id() != id)
174	                    .forEach(r -> weighRecordRepository.markSuperseded(r.id()));
175	        }
176	
177	        return toWeighResponse(weighRecordRepository.findById(id), false, false);
178	    }
179	
180	    /**
181	     * 依据在案权威过磅记录生成处罚决定（幂等）。
182	     */
183	    @Transactional
184	    public DecisionResponse issueDecision(DecisionRequest req) {
185	        Instant now = Instant.now(clock);
186	        String fingerprint = Fingerprints.of(
187	                "DECISION", req.requestId(), req.plateNo(), req.stationCode(), req.weighTime().toString());
188	
189	        DecisionRow existing = decisionRepository.findByRequestId(req.requestId());
190	        if (existing != null) {
191	            if (!existing.fingerprint().equals(fingerprint)) {
192	                throw ApiException.conflict("IDEMPOTENT_PARAM_CONFLICT",
193	                        "requestId 已存在但业务参数不一致，拒绝产生新文书");
194	            }
195	            return toDecisionResponse(existing, true);
196	        }
197	
198	        CaseRow caseRow = requireOpenCase(req.plateNo(), req.stationCode(), req.weighTime());
199	        WeighRecordRow authoritative = weighRecordRepository.findAuthoritative(
200	                req.plateNo(), req.stationCode(), req.weighTime());
201	        if (authoritative == null) {
202	            throw ApiException.notFound("案件缺少可作为判定依据的过磅记录");
203	        }
204	
205	        DecisionTier tier = DecisionTier.valueOf(authoritative.tier());
206	        DocType docType = switch (tier) {
207	            case FINE_POINTS -> DocType.PENALTY;
208	            case UNLOAD_RELEASE -> DocType.UNLOAD_RELEASE;
209	            case NO_OVERLOAD -> DocType.NO_ACTION;
210	        };
211	        BigDecimal fineAmount = BigDecimal.ZERO.setScale(2);
212	        int points = 0;
213	        if (tier == DecisionTier.FINE_POINTS) {
214	            fineAmount = OverloadRules.FINE_AMOUNT;
215	            points = OverloadRules.FINE_POINTS;
216	        }
217	
218	        String docNo = sequenceRepository.nextDocNo();
219	        DecisionRow row = new DecisionRow(
220	                null, req.requestId(), fingerprint, docNo, caseRow.id(), docType.name(), tier.name(),
221	                authoritative.totalKg(), authoritative.limitKg(), authoritative.overloadRate(),
222	                fineAmount, points, DecisionStatus.ACTIVE.name(), now, null, now);
223	        long id;
224	        try {
225	            id = decisionRepository.insert(row);
226	        } catch (DuplicateKeyException e) {
227	            DecisionRow raced = decisionRepository.findByRequestId(req.requestId());
228	            if (raced == null) {
229	                throw e;
230	            }
231	            if (!raced.fingerprint().equals(fingerprint)) {
232	                throw ApiException.conflict("IDEMPOTENT_PARAM_CONFLICT",
233	                        "requestId 已存在但业务参数不一致，拒绝产生新文书");
234	            }
235	            return toDecisionResponse(raced, true);
236	        }
237	
238	        if (points > 0) {
239	            ledgerRepository.appendPoints(req.plateNo(), caseRow.id(), id, points, REASON_PENALTY, now);
240	        }
241	        if (fineAmount.signum() > 0) {
242	            ledgerRepository.appendFine(req.plateNo(), caseRow.id(), id, fineAmount, REASON_PENALTY, now);
243	        }
244	        return toDecisionResponse(decisionRepository.findByRequestId(req.requestId()), false);
245	    }
246	
247	    /**
248	     * 复检申请：处罚送达后 7 个自然日（UTC 日界）内一次，恰第 7 日受理，逾期拒绝；同一案件唯一受理。
249	     */
250	    @Transactional
251	    public ReviewResponse applyReview(ReviewApplyRequest req) {
252	        Instant now = Instant.now(clock);
253	        String fingerprint = Fingerprints.of(
254	                "REVIEW_APPLY", req.requestId(), req.plateNo(), req.stationCode(),
255	                req.weighTime().toString(), req.reason());
256	
257	        ReviewRow existing = reviewRepository.findByRequestId(req.requestId());
258	        if (existing != null) {
259	            if (!existing.fingerprint().equals(fingerprint)) {
260	                throw ApiException.conflict("IDEMPOTENT_PARAM_CONFLICT",
261	                        "requestId 已存在但业务参数不一致，拒绝重复申请");
262	            }
263	            return toReviewResponse(existing, true);
264	        }
265	
266	        CaseRow caseRow = requireCase(req.plateNo(), req.stationCode(), req.weighTime());
267	        DecisionRow decision = decisionRepository.findActiveByCaseId(caseRow.id());
268	        if (decision == null) {
269	            throw ApiException.unprocessable("NO_ACTIVE_PENALTY", "案件不存在生效处罚决定，不能申请复检");
270	        }
271	        if (decision.points() <= 0 && decision.fineAmount().signum() == 0) {
272	            throw ApiException.unprocessable("NO_PENALTY_REVIEWABLE", "无罚款记分的处理决定不适用复检申诉");
273	        }
274	        if (!withinSevenUtcDays(decision.servedAt(), now)) {
275	            throw ApiException.unprocessable("REVIEW_WINDOW_EXPIRED",
276	                    "复检申请已超过送达后 7 个自然日（UTC 日界），逾期拒绝");
277	        }
278	
279	        ReviewRow row = new ReviewRow(null, req.requestId(), fingerprint, caseRow.id(), decision.id(),
280	                req.reason(), ReviewStatus.UNDER_REVIEW.name(), now, null, null, null, null);
281	        long id;
282	        try {
283	            id = reviewRepository.insert(row);
284	        } catch (DuplicateKeyException e) {
285	            // 同一案件并发复检：uk_review_case 保证唯一受理
286	            ReviewRow raced = reviewRepository.findByCaseId(caseRow.id());
287	            if (raced != null && raced.requestId().equals(req.requestId())) {
288	                if (!raced.fingerprint().equals(fingerprint)) {
289	                    throw ApiException.conflict("IDEMPOTENT_PARAM_CONFLICT",
290	                            "requestId 已存在但业务参数不一致，拒绝重复申请");
291	                }
292	                return toReviewResponse(raced, true);
293	            }
294	            throw ApiException.conflict("REVIEW_ALREADY_EXISTS", "同一案件仅受理一次复检申请");
295	        }
296	        return toReviewResponse(reviewRepository.findByIdForUpdate(id), false);
297	    }
298	
299	    /**
300	     * 复检结论：推翻时同一事务内撤销原决定、退还记分与罚款并生成撤销文书，保证原子性。
301	     */
302	    @Transactional
303	    public ReviewResponse concludeReview(ReviewConcludeRequest req) {
304	        Instant now = Instant.now(clock);
305	        String fingerprint = Fingerprints.of(
306	                "REVIEW_CONCLUDE", req.requestId(), req.plateNo(), req.stationCode(),
307	                req.weighTime().toString(), String.valueOf(req.overturn()),
308	                req.recheckTotalKg() == null ? "" : req.recheckTotalKg().stripTrailingZeros().toPlainString());
309	
310	        ReviewRow existing = reviewRepository.findByConcludeRequestId(req.requestId());
311	        if (existing != null) {
312	            if (!existing.concludeFingerprint().equals(fingerprint)) {
313	                throw ApiException.conflict("IDEMPOTENT_PARAM_CONFLICT",
314	                        "结论 requestId 已存在但业务参数不一致，拒绝重复结论");
315	            }
316	            return toReviewResponse(existing, true);
317	        }
318	
319	        CaseRow caseRow = requireCase(req.plateNo(), req.stationCode(), req.weighTime());
320	        ReviewRow review = reviewRepository.findByCaseId(caseRow.id());
321	        if (review == null) {
322	            throw ApiException.notFound("案件未查询到已受理的复检申请");
323	        }
324	        review = reviewRepository.findByIdForUpdate(review.id());
325	        if (!ReviewStatus.UNDER_REVIEW.name().equals(review.status())) {
326	            throw ApiException.conflict("REVIEW_ALREADY_CONCLUDED", "复检申请已有结论");
327	        }
328	
329	        ReviewStatus target = Boolean.TRUE.equals(req.overturn())
330	                ? ReviewStatus.OVERTURNED : ReviewStatus.UPHELD;
331	
332	        if (target == ReviewStatus.OVERTURNED) {
333	            if (req.recheckTotalKg() == null) {
334	                throw ApiException.unprocessable("RECHECK_WEIGHT_REQUIRED", "推翻原处罚须提供静态复检总重");
335	            }
336	            DecisionRow decision = decisionRepository.findByIdForUpdate(review.decisionId());
337	            if (decision == null || !DecisionStatus.ACTIVE.name().equals(decision.status())) {
338	                throw ApiException.unprocessable("NO_ACTIVE_PENALTY", "原处罚决定已不生效，不能撤销");
339	            }
340	            // 同一事务：撤销原决定 -> 退还记分/罚款 -> 生成撤销文书；任一失败整体回滚
341	            int revoked = decisionRepository.revoke(decision.id(), now);
342	            if (revoked != 1) {
343	                throw ApiException.conflict("PENALTY_REVOKE_RACE", "原处罚决定状态已变化，撤销失败");
344	            }
345	            if (decision.points() > 0) {
346	                ledgerRepository.appendPoints(req.plateNo(), caseRow.id(), decision.id(),
347	                        -decision.points(), REASON_REFUND, now);
348	            }
349	            if (decision.fineAmount().signum() > 0) {
350	                ledgerRepository.appendFine(req.plateNo(), caseRow.id(), decision.id(),
351	                        decision.fineAmount().negate(), REASON_REFUND, now);
352	            }
353	            String revocationNo = sequenceRepository.nextDocNo();
354	            DecisionRow revocation = new DecisionRow(
355	                    null, "REV-" + req.requestId(),
356	                    Fingerprints.of("REVOCATION", req.requestId(), String.valueOf(decision.id())),
357	                    revocationNo, caseRow.id(), DocType.REVOCATION.name(), decision.tier(),
358	                    req.recheckTotalKg(), decision.limitKg(),
359	                    OverloadRules.overloadRate(req.recheckTotalKg(), decision.limitKg()),
360	                    BigDecimal.ZERO.setScale(2), 0, DecisionStatus.ACTIVE.name(), now, null, now);
361	            decisionRepository.insert(revocation);
362	        }
363	
364	        int updated = reviewRepository.conclude(review.id(), target.name(), req.requestId(), fingerprint,
365	                now, req.recheckTotalKg());
366	        if (updated != 1) {
367	            throw ApiException.conflict("REVIEW_ALREADY_CONCLUDED", "复检申请已有结论");
368	        }
369	        return toReviewResponse(reviewRepository.findByCaseId(caseRow.id()), false);
370	    }
371	
372	    /**
373	     * 案件结案（终态）：重复结案返回幂等成功，不产生新文书。
374	     */
375	    @Transactional
376	    public CaseResponse closeCase(com.example.starter.weight.api.dto.CloseCaseRequest req) {
377	        Instant now = Instant.now(clock);
378	        String fingerprint = Fingerprints.of(
379	                "CLOSE", req.requestId(), req.plateNo(), req.stationCode(), req.weighTime().toString());
380	
381	        CaseRow byCloseReq = caseRepository.findByCloseRequestId(req.requestId());
382	        if (byCloseReq != null) {
383	            if (!byCloseReq.closeFingerprint().equals(fingerprint)) {
384	                throw ApiException.conflict("IDEMPOTENT_PARAM_CONFLICT",
385	                        "结案 requestId 已存在但业务参数不一致，拒绝重复结案");
386	            }
387	            return toCaseResponse(byCloseReq, true);
388	        }
389	
390	        CaseRow caseRow = requireCase(req.plateNo(), req.stationCode(), req.weighTime());
391	        int closed = caseRepository.close(caseRow.id(), req.requestId(), fingerprint, now);
392	        CaseRow latest = caseRepository.findById(caseRow.id());
393	        // closed == 0 表示此前已结案：终态下重复结案仍返回幂等成功
394	        return toCaseResponse(latest, closed == 0);
395	    }
396	
397	    /**
398	     * 查询案件与文书链（含撤销文书）。
399	     */
400	    @Transactional(readOnly = true)
401	    public CaseResponse getCase(String caseNo) {
402	        CaseRow caseRow = caseRepository.findByCaseNo(caseNo);
403	        if (caseRow == null) {
404	            throw ApiException.notFound("案件不存在: " + caseNo);
405	        }
406	        return toCaseResponse(caseRow, false);
407	    }
408	
409	    // ---- 内部方法 ----
410	
411	    private CaseRow createCase(String plateNo, String stationCode, Instant weighTime, Instant now) {
412	        String caseNo = sequenceRepository.nextCaseNo();
413	        CaseRow row = new CaseRow(null, caseNo, plateNo, stationCode, weighTime,
414	                CaseStatus.OPEN.name(), null, null, null, now);
415	        try {
416	            caseRepository.insert(row);
417	        } catch (DuplicateKeyException e) {
418	            CaseRow raced = caseRepository.findByBizKey(plateNo, stationCode, weighTime);
419	            if (raced != null) {
420	                return raced;
421	            }
422	            throw e;
423	        }
424	        return caseRepository.findByCaseNo(caseNo);
425	    }
426	
427	    /**
428	     * 判定非迟到记录角色：静态复检优先；静态已在案时后到动态降级保留。
429	     */
430	    private String resolveLiveRole(String plateNo, String stationCode, Instant weighTime, WeighMode mode) {
431	        if (mode == WeighMode.STATIC) {
432	            return RecordRole.AUTHORITATIVE.name();
433	        }
434	        List<WeighRecordRow> all = weighRecordRepository.findAllByBizKey(plateNo, stationCode, weighTime);
435	        boolean hasStatic = all.stream().anyMatch(r -> r.mode().equals(WeighMode.STATIC.name()));
436	        return hasStatic ? RecordRole.SUPERSEDED.name() : RecordRole.AUTHORITATIVE.name();
437	    }
438	
439	    private VehicleRow requireVehicle(String plateNo) {
440	        VehicleRow vehicle = referenceRepository.findVehicle(plateNo);
441	        if (vehicle == null) {
442	            throw ApiException.notFound("车辆档案不存在: " + plateNo);
443	        }
444	        return vehicle;
445	    }
446	
447	    private StationRow requireStation(String stationCode) {
448	        StationRow station = referenceRepository.findStation(stationCode);
449	        if (station == null) {
450	            throw ApiException.notFound("检测站不存在: " + stationCode);
451	        }
452	        return station;
453	    }
454	
455	    private CaseRow requireCase(String plateNo, String stationCode, Instant weighTime) {
456	        CaseRow caseRow = caseRepository.findByBizKey(plateNo, stationCode, weighTime);
457	        if (caseRow == null) {
458	            throw ApiException.notFound("案件不存在（车牌+检测站+过磅时刻未匹配）");
459	        }
460	        return caseRow;
461	    }
462	
463	    private CaseRow requireOpenCase(String plateNo, String stationCode, Instant weighTime) {
464	        CaseRow caseRow = requireCase(plateNo, stationCode, weighTime);
465	        if (CaseStatus.CLOSED.name().equals(caseRow.status())) {
466	            throw ApiException.conflict("CASE_CLOSED", "案件已结案，不能再生成新文书");
467	        }
468	        return caseRow;
469	    }
470	
471	    /**
472	     * 送达后 7 个自然日（UTC 日界）内：申请日 - 送达日 &lt;= 7，恰第 7 日受理，第 8 日起拒绝。
473	     */
474	    private boolean withinSevenUtcDays(Instant servedAt, Instant appliedAt) {
475	        LocalDate servedDay = servedAt.atOffset(ZoneOffset.UTC).toLocalDate();
476	        LocalDate appliedDay = appliedAt.atOffset(ZoneOffset.UTC).toLocalDate();
477	        long days = ChronoUnit.DAYS.between(servedDay, appliedDay);
478	        return days >= 0 && days <= 7;
479	    }
480	
481	    private WeighResponse toWeighResponse(WeighRecordRow row, boolean replayed, boolean deduped) {
482	        if (row == null) {
483	            throw ApiException.notFound("过磅记录不存在");
484	        }
485	        String caseNo = null;
486	        if (row.caseId() != null) {
487	            CaseRow caseRow = caseRepository.findById(row.caseId());
488	            caseNo = caseRow == null ? null : caseRow.caseNo();
489	        }
490	        return new WeighResponse(row.id(), row.plateNo(), row.stationCode(), row.weighTime(),
491	                row.mode(), row.totalKg(), row.limitKg(), row.overloadRate(), row.tier(), row.role(),
492	                caseNo, RecordRole.LATE_EVIDENCE.name().equals(row.role()), replayed, deduped);
493	    }
494	
495	    private DecisionResponse toDecisionResponse(DecisionRow row, boolean replayed) {
496	        if (row == null) {
497	            throw ApiException.notFound("处罚决定不存在");
498	        }
499	        CaseRow caseRow = caseRepository.findById(row.caseId());
500	        return new DecisionResponse(row.id(), row.docNo(), caseRow == null ? null : caseRow.caseNo(),
501	                row.docType(), row.tier(), row.totalKg(), row.limitKg(), row.overloadRate(),
502	                row.fineAmount(), row.points(), row.status(), row.servedAt(), replayed);
503	    }
504	
505	    private ReviewResponse toReviewResponse(ReviewRow row, boolean replayed) {
506	        if (row == null) {
507	            throw ApiException.notFound("复检申请不存在");
508	        }
509	        CaseRow caseRow = caseRepository.findById(row.caseId());
510	        return new ReviewResponse(row.id(), caseRow == null ? null : caseRow.caseNo(),
511	                row.decisionId(), row.status(), row.appliedAt(), row.concludedAt(), replayed);
512	    }
513	
514	    private CaseResponse toCaseResponse(CaseRow caseRow, boolean replayed) {
515	        List<DecisionResponse> decisions = decisionRepository.findByCaseId(caseRow.id()).stream()
516	                .map(d -> toDecisionResponse(d, false))
517	                .toList();
518	        return new CaseResponse(caseRow.caseNo(), caseRow.plateNo(), caseRow.status(),
519	                caseRow.closedAt(), decisions, replayed);
520	    }
521	}
