            return jdbc.queryForObject(
                    "SELECT * FROM enforcement_case WHERE plate_no = ? AND station_code = ? AND weigh_time = ?",
                    MAPPER, plateNo, stationCode, Timestamp.from(weighTime));
        } catch (EmptyResultDataAccessException e) {
            return null;
        }
    }

    /**
